// frontend/src/features/tickets/TicketCreate.jsx - Enhanced UI with All Requested Fields
// Fields: title, description, priority, assigned_to (Admin only), confidential_notes (Admin only), attachments
// UI inspired by Sanchar Helpdesk PDF: Purple theme, clean sections, modern and attractive
import React, { useState } from "react";
import api from "../../api/axios"; // Adjust path if needed
import { useNavigate } from "react-router-dom";
import { useSelector } from "react-redux";

const TicketCreate = () => {
  const [form, setForm] = useState({
    title: "",
    description: "",
    priority: "LOW",
    assigned_to: "", // Admin only - will be sent as ID
    confidential_notes: "",
  });
  const [file, setFile] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const navigate = useNavigate();

  const user = useSelector((state) => state.auth.user);
  const isAdmin = user?.is_admin || user?.role === "admin"; // Adjust based on your auth structure

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleFileChange = (e) => {
    setFile(e.target.files[0]);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      const data = new FormData();
      data.append("title", form.title);
      data.append("description", form.description);
      data.append("priority", form.priority);
      if (isAdmin && form.assigned_to) data.append("assigned_to", form.assigned_to); // Only admins can assign
      if (isAdmin && form.confidential_notes) data.append("confidential_notes", form.confidential_notes);
      if (file) data.append("attachments", file); // Backend expects 'attachments' (adjust if needed)

      await api.post("/tickets/", data, {
        headers: { "Content-Type": "multipart/form-data" },
      });

      navigate("/employee");
    } catch (err) {
      console.error("Ticket creation error:", err);
      setError(
        err.response?.data?.detail ||
          err.response?.data?.message ||
          "Failed to create ticket. Please try again."
      );
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={styles.container}>
      <h3 style={styles.title}>Create New Sanchar Ticket</h3>

      {error && <div style={styles.errorAlert}>{error}</div>}

      <form onSubmit={handleSubmit} style={styles.form}>
        {/* Ticket Details */}
        <div style={styles.section}>
          <h4 style={styles.sectionTitle}>Ticket Details</h4>
          <div style={styles.inputGroup}>
            <label style={styles.label}>Title *</label>
            <input
              type="text"
              name="title"
              style={styles.input}
              placeholder="Enter brief title of the issue"
              value={form.title}
              onChange={handleChange}
              required
            />
          </div>
          <div style={styles.inputGroup}>
            <label style={styles.label}>Description *</label>
            <textarea
              name="description"
              style={styles.textarea}
              rows="5"
              placeholder="Provide detailed description of the issue..."
              value={form.description}
              onChange={handleChange}
              required
            />
          </div>
          <div style={styles.inputGroup}>
            <label style={styles.label}>Priority</label>
            <select
              name="priority"
              style={styles.select}
              value={form.priority}
              onChange={handleChange}
            >
              <option value="LOW">Low</option>
              <option value="MEDIUM">Medium</option>
              <option value="HIGH">High</option>
            </select>
          </div>
        </div>

        {/* Admin-Only Fields */}
        {isAdmin && (
          <div style={styles.section}>
            <h4 style={styles.sectionTitle}>Admin Controls</h4>
            <div style={styles.inputGroup}>
              <label style={styles.label}>Assign To (User ID)</label>
              <input
                type="text"
                name="assigned_to"
                style={styles.input}
                placeholder="Enter user ID to assign (optional)"
                value={form.assigned_to}
                onChange={handleChange}
              />
            </div>
            <div style={styles.inputGroup}>
              <label style={styles.label}>Confidential Notes (Encrypted)</label>
              <textarea
                name="confidential_notes"
                style={styles.textarea}
                rows="3"
                placeholder="Internal notes (only visible to admins)"
                value={form.confidential_notes}
                onChange={handleChange}
              />
            </div>
          </div>
        )}

        {/* Attachments */}
        <div style={styles.section}>
          <h4 style={styles.sectionTitle}>Attachments</h4>
          <div style={styles.inputGroup}>
            <label style={styles.label}>Upload File (Image/PDF/Doc)</label>
            <input
              type="file"
              style={styles.fileInput}
              accept="image/*,.pdf,.doc,.docx"
              onChange={handleFileChange}
            />
            <small style={styles.smallText}>
              Optional: Upload evidence or logs (max 5MB recommended)
            </small>
          </div>
        </div>

        <button
          type="submit"
          style={{
            ...styles.submitButton,
            opacity: loading ? 0.7 : 1,
          }}
          disabled={loading}
        >
          {loading ? "Submitting..." : "Create Ticket"}
        </button>
      </form>
    </div>
  );
};

// Modern, Clean Styles - Purple Theme Matching Sanchar Helpdesk PDF
const styles = {
  container: {
    padding: "40px 20px",
    maxWidth: "800px",
    margin: "0 auto",
    background: "linear-gradient(to bottom, #f9faff, #ffffff)",
    minHeight: "100vh",
    fontFamily: "Arial, sans-serif",
  },
  title: {
    fontSize: "32px",
    textAlign: "center",
    marginBottom: "40px",
    color: "#4527a0",
    fontWeight: "700",
  },
  errorAlert: {
    padding: "16px",
    background: "linear-gradient(135deg, #ff4d4f, #cf1322)",
    color: "#ffffff",
    borderRadius: "8px",
    marginBottom: "24px",
    textAlign: "center",
  },
  form: {
    background: "#ffffff",
    padding: "32px",
    borderRadius: "16px",
    boxShadow: "0 8px 24px rgba(0,0,0,0.1)",
  },
  section: {
    marginBottom: "32px",
  },
  sectionTitle: {
    fontSize: "22px",
    marginBottom: "20px",
    color: "#4527a0",
    fontWeight: "600",
    borderBottom: "2px solid #4527a0",
    paddingBottom: "8px",
  },
  inputGroup: {
    marginBottom: "20px",
  },
  label: {
    display: "block",
    fontSize: "15px",
    fontWeight: "600",
    color: "#1a1a1a",
    marginBottom: "8px",
  },
  input: {
    width: "100%",
    padding: "12px",
    border: "1px solid #d9d9d9",
    borderRadius: "8px",
    fontSize: "15px",
    transition: "border-color 0.2s",
  },
  textarea: {
    width: "100%",
    padding: "12px",
    border: "1px solid #d9d9d9",
    borderRadius: "8px",
    fontSize: "15px",
    resize: "vertical",
  },
  select: {
    width: "100%",
    padding: "12px",
    border: "1px solid #d9d9d9",
    borderRadius: "8px",
    fontSize: "15px",
    background: "#ffffff",
    cursor: "pointer",
  },
  fileInput: {
    width: "100%",
    padding: "8px",
    border: "1px solid #d9d9d9",
    borderRadius: "8px",
    fontSize: "15px",
  },
  smallText: {
    display: "block",
    fontSize: "13px",
    color: "#7a7a7a",
    marginTop: "8px",
  },
  submitButton: {
    width: "100%",
    padding: "14px",
    background: "linear-gradient(135deg, #7c4dff, #4527a0)",
    color: "#ffffff",
    border: "none",
    borderRadius: "8px",
    fontSize: "18px",
    fontWeight: "600",
    cursor: "pointer",
    transition: "opacity 0.2s",
  },
};

export default TicketCreate;
